// NutriX dish table, generated by scripts/build_dishes.py from the NutriX Food Dataset.
// - 59 everyday dishes from INDB (Indian Nutrient Databank), converted to katori/piece/glass/cup portions.
//   Katori = 180 g (dals, curries), 150 g (rice and grain dishes), 120 g (dry sabzi).
// - 798 more INDB recipes (A to Z; deep-fried rows excluded because INDB counts all frying oil).
// - 96 reference dishes from indian_food_nutrition_dataset.csv (generic per-serving estimates).
// - 216 regional dishes from the 217-class regional layer, per-serving values (estimates; duplicate Basundi removed).
// checked = false until a dietitian verifies the row.
import data from "@/data/dishes.json";

export type Unit = "katori" | "piece" | "glass" | "cup" | "serving";

export interface Nutrients {
  kcal: number;
  carbs: number;
  protein: number;
  fat: number;
  fibre: number;
  sugar?: number | null;
}

export interface Dish {
  id: string;
  name: string;
  aliases: string[];
  unit: Unit;
  unitGrams: number | null; // grams in one unit, when known
  perUnit: Nutrients; // nutrition for ONE unit (1 katori, 1 piece, 1 serving…)
  source: string; // "INDB" | "Regional layer (estimate)"
  sourceCode: string;
  sourceName: string;
  cuisine: string;
  mealType?: string;
  dietaryTag?: string;
  servingNote?: string | null;
  checked: boolean;
}

export const DISHES: Dish[] = data as Dish[];
export const DISH_BY_ID: Record<string, Dish> = Object.fromEntries(DISHES.map((d) => [d.id, d]));
export const EVERYDAY = DISHES.filter((d) => d.cuisine === "Everyday Indian");
export const REFERENCE = DISHES.filter((d) => d.source.startsWith("Reference"));
export const REGIONAL = DISHES.filter((d) => d.source.startsWith("Regional"));
export const sourceLabel = (d: Dish) => (d.source === "INDB" ? `INDB ${d.sourceCode}` : d.source.startsWith("Reference") ? "reference estimate" : "regional estimate");

/** Search dishes by name or alias. Everyday dishes rank first, then names that start with the query. */
const normAll = (s: string) => s.toLowerCase().replace(/[^a-z ]/g, " ").replace(/\s+/g, " ").trim();
export function searchDishes(q: string, limit = 12): Dish[] {
  const n = normAll(q);
  if (!n) return EVERYDAY.slice(0, limit);
  const words = n.split(" ");
  const scored: { d: Dish; s: number }[] = [];
  for (const d of DISHES) {
    const hay = normAll([d.name, d.sourceName, ...d.aliases].join(" "));
    if (!words.every((w) => hay.includes(w))) continue;
    let s = 0;
    if (d.cuisine === "Everyday Indian") s += 100;
    else if (d.source.startsWith("Reference")) s += 40;
    else if (d.source === "INDB") s += 20;
    if (normAll(d.name).startsWith(n) || d.aliases.some((a) => normAll(a).startsWith(n))) s += 50;
    s -= d.name.length / 10;
    scored.push({ d, s });
  }
  return scored.sort((a, b) => b.s - a.s).slice(0, limit).map((x) => x.d);
}

const norm = (s: string) => s.toLowerCase().replace(/\(.*?\)/g, " ").replace(/[^a-z ]/g, " ").replace(/\s+/g, " ").trim();

/** Map a free-text dish name (e.g. from the AI) to a dish in the table. Everyday dishes win ties. */
export function matchDish(name: string): Dish | null {
  const n = norm(name);
  if (!n) return null;
  for (const d of DISHES) {
    if (norm(d.name) === n || d.aliases.some((a) => norm(a) === n) || d.id.replace(/_/g, " ") === n) return d;
  }
  let best: { d: Dish; len: number } | null = null;
  for (const d of [...EVERYDAY, ...REFERENCE]) {
    for (const a of [d.name.replace(" (reference)", ""), ...d.aliases]) {
      const na = norm(a);
      if (na.length >= 3 && (n.includes(na) || na.includes(n)) && (!best || na.length > best.len)) best = { d, len: na.length };
    }
  }
  return best?.d ?? null;
}

export function nutritionFor(dishId: string, portion: number) {
  const d = DISH_BY_ID[dishId];
  if (!d) return { grams: 0, kcal: 0, carbs: 0, protein: 0, fat: 0, fibre: 0 };
  const p = d.perUnit;
  return {
    grams: d.unitGrams ? Math.round(d.unitGrams * portion) : 0,
    kcal: Math.round(p.kcal * portion),
    carbs: Math.round(p.carbs * portion),
    protein: Math.round(p.protein * portion),
    fat: Math.round(p.fat * portion),
    fibre: Math.round((p.fibre || 0) * portion * 10) / 10,
  };
}

export const PORTION_OPTIONS: Record<Unit, number[]> = {
  katori: [0.5, 1, 1.5, 2],
  piece: [1, 2, 3, 4],
  glass: [0.5, 1, 2],
  cup: [0.5, 1, 2],
  serving: [0.5, 1, 1.5, 2],
};

export const UNIT_LABEL: Record<Unit, string> = {
  katori: "Katori",
  piece: "Pieces",
  glass: "Glass",
  cup: "Cup",
  serving: "Servings",
};
